const $=id=>document.getElementById(id), fmt=v=>Number(v).toFixed(1).replace('.',','), signed=v=>(v>=0?'+':'−')+fmt(Math.abs(v));
const NS='http://www.w3.org/2000/svg';function el(t,a={},text){const n=document.createElementNS(NS,t);Object.entries(a).forEach(([k,v])=>n.setAttribute(k,v));if(text!==undefined)n.textContent=text;return n}
function pos(v,r){const a=(180-180*Math.max(-30,Math.min(30,v))/30)/2*Math.PI/180;return [350+r*Math.cos(a),295-r*Math.sin(a)]}
function sector(l,h,outer,inner){let p=pos(l,outer),q=pos(h,outer),u=pos(h,inner),v=pos(l,inner);return `M${p} A${outer},${outer} 0 0 1 ${q} L${u} A${inner},${inner} 0 0 0 ${v} Z`}
function gauge(r){let svg=$('gauge');svg.replaceChildren();for(const [l,h,c] of [[-30,-15,'#009ce4'],[-15,-5,'#55b9e6'],[-5,-1,'#a8dff5'],[-1,1,'#ddd'],[1,5,'#f4e3ac'],[5,15,'#e8c65c'],[15,30,'#d6a211']])svg.append(el('path',{d:sector(l,h,250,150),fill:c,stroke:'white','stroke-width':3}));svg.append(el('text',{x:350,y:22,'text-anchor':'middle',fill:'#777','font-size':12},'EMPATE'));for(const v of [-30,-20,-10,10,20,30]){let p=pos(v,273);svg.append(el('text',{x:p[0],y:p[1]+5,'text-anchor':'middle',fill:'#777','font-size':13},'+'+Math.abs(v)))}let [lo,hi]=r.margen_banda;svg.append(el('path',{d:sector(lo,hi,143,0),fill:'#555',opacity:.17}));const p=pos(r.margen,245),ang=Math.atan2(295-p[1],p[0]-350),nx=7*Math.sin(ang),ny=7*Math.cos(ang);svg.append(el('polygon',{points:`${p} ${350+nx},${295+ny} ${350-nx},${295-ny}`,fill:'#171717'}));svg.append(el('circle',{cx:350,cy:295,r:12,fill:'#171717'}));svg.append(el('text',{x:95,y:345,'text-anchor':'middle',fill:'#009ce4','font-size':13},'VENTAJA FDT'));svg.append(el('text',{x:605,y:345,'text-anchor':'middle',fill:'#a67c00','font-size':13},'VENTAJA JXC'))}
function draw(){let r=D.samples[$('scheme').value];gauge(r);$('fp').textContent=fmt(100*r.prob_primero[1])+' %';$('jp').textContent=fmt(100*r.prob_primero[0])+' %';$('margin').textContent=(r.margen>=0?'JXC +':'FDT +')+fmt(Math.abs(r.margen));$('band').textContent='Banda nominal 95 % del margen JXC−FDT: '+signed(r.margen_banda[0])+' a '+signed(r.margen_banda[1]);$('support').textContent='30 mesas · '+r.circuitos+' circuitos · colección 1 de 100';$('actualmargin').textContent='Resultado del universo evaluado: JXC +'+fmt(D.real.margen_JXC_FDT)+' · error de esta colección: '+signed(r.margen-D.real.margen_JXC_FDT);
$('national').innerHTML=D.forces.map((f,i)=>`<tr><td><span class="sw" style="background:${D.colors[f]}"></span>${D.names[f]}</td><td><b>${fmt(r.punto[i])} %</b></td><td>${fmt(r.lo[i])}–${fmt(r.hi[i])}</td><td class="actual">${fmt(D.real.nacional[f])} %</td><td class="actual">${signed(r.punto[i]-D.real.nacional[f])}</td></tr>`).join('');$('district').innerHTML=r.distritos.map((d,i)=>`<tr><td>${D.districts[d]}</td>${r.porcentaje_distrito[i].map(v=>`<td>${fmt(v)}</td>`).join('')}</tr>`).join('');let map=$('map');map.replaceChildren();map.setAttribute('viewBox',D.view.join(' '));for(const [d,path] of Object.entries(D.paths)){let i=r.distritos.indexOf(d);if(i<0)continue;let vals=r.porcentaje_distrito[i],winner=D.forces[vals.indexOf(Math.max(...vals))];let n=el('path',{d:path,fill:D.colors[winner],stroke:'white','stroke-width':2});n.append(el('title',{},D.districts[d]+' · '+D.forces.map((f,j)=>f+' '+fmt(vals[j])+' %').join(' / ')));map.append(n)}document.body.classList.toggle('hide-real',!$('showreal').checked)}
$('scheme').innerHTML=Object.entries(D.schemes).map(([k,v])=>`<option value="${k}">${v}</option>`).join('');$('scheme').value='twitter';$('scheme').onchange=draw;$('showreal').onchange=draw;$('legend').innerHTML=D.forces.map(f=>`<span><i class="sw" style="background:${D.colors[f]}"></i>${f}</span>`).join('');$('comparison').innerHTML=Object.entries(D.schemes).map(([k,label])=>{let r=D.samples[k];return `<tr><td>${label}</td><td>${signed(r.margen)}</td><td>${signed(r.margen_banda[0])} a ${signed(r.margen_banda[1])}</td><td class="actual">${signed(r.margen-D.real.margen_JXC_FDT)}</td></tr>`}).join('');draw();
